import{_ as d,o as e,c as o,aO as c}from"./chunks/framework.vjUPZZJn.js";const s=JSON.parse('{"title":"Git 常用命令速查","description":"","frontmatter":{"date":"2026-10-08T20:00:00.000Z","title":"Git 常用命令速查","source":[[["1-知识/工具/Git/git 命令整理"]],[["1-知识/工具/Git/修改已 push 的 commit 信息"]]],"tags":["工具","教程手册","git"],"categories":["工具"],"permalink":"/pages/59d122"},"headers":[],"relativePath":"工具/Git 常用命令速查.md","filePath":"工具/Git 常用命令速查.md","lastUpdated":1791440489000}'),r={name:"工具/Git 常用命令速查.md"};function i(a,t,g,l,n,h){return e(),o("div",null,[...t[0]||(t[0]=[c('<h1 id="git-常用命令速查" tabindex="-1">Git 常用命令速查 <a class="header-anchor" href="#git-常用命令速查" aria-label="Permalink to &quot;Git 常用命令速查&quot;">​</a></h1> <p>按功能分类整理 Git 常用命令，覆盖日常开发的配置、提交、分支、远程协作与标签操作，末尾单独补充「修改已推送的提交信息」这一常见场景。适合放在手边随查随用。</p> <h2 id="命令速查表" tabindex="-1">命令速查表 <a class="header-anchor" href="#命令速查表" aria-label="Permalink to &quot;命令速查表&quot;">​</a></h2> <table tabindex="0"><thead><tr><th>类别</th> <th>命令</th> <th>说明</th></tr></thead> <tbody><tr><td>配置</td> <td><code>git config --global user.name &quot;Your Name&quot;</code></td> <td>设置全局用户名</td></tr> <tr><td></td> <td><code>git config --global user.email &quot;email@example.com&quot;</code></td> <td>设置全局邮箱</td></tr> <tr><td></td> <td><code>git config --list</code></td> <td>查看当前配置</td></tr> <tr><td>初始化</td> <td><code>git init</code></td> <td>初始化一个新的 Git 仓库</td></tr> <tr><td></td> <td><code>git clone &lt;url&gt;</code></td> <td>克隆远程仓库到本地</td></tr> <tr><td>查看状态</td> <td><code>git status</code></td> <td>查看工作区状态（哪些文件被修改、暂存等）</td></tr> <tr><td>添加与提交</td> <td><code>git add &lt;file&gt;</code></td> <td>将指定文件添加到暂存区</td></tr> <tr><td></td> <td><code>git add .</code></td> <td>添加当前目录所有更改到暂存区</td></tr> <tr><td></td> <td><code>git commit -m &quot;commit message&quot;</code></td> <td>提交暂存区内容到本地仓库，并附带提交信息</td></tr> <tr><td>查看历史</td> <td><code>git log</code></td> <td>查看提交历史（详细）</td></tr> <tr><td></td> <td><code>git log --oneline</code></td> <td>以单行形式显示提交历史</td></tr> <tr><td></td> <td><code>git log --graph --all --oneline</code></td> <td>图形化显示所有分支的提交历史</td></tr> <tr><td>差异比较</td> <td><code>git diff</code></td> <td>查看工作区与暂存区之间的差异</td></tr> <tr><td></td> <td><code>git diff --staged</code> 或 <code>git diff --cached</code></td> <td>查看暂存区与最新提交之间的差异（两者等价）</td></tr> <tr><td>撤销操作</td> <td><code>git checkout -- &lt;file&gt;</code></td> <td>丢弃工作区对文件的修改（恢复到最近一次暂存/提交状态）</td></tr> <tr><td></td> <td><code>git reset HEAD &lt;file&gt;</code></td> <td>从暂存区移除文件（保留工作区修改）</td></tr> <tr><td></td> <td><code>git reset --hard HEAD~1</code></td> <td>回退到上一个提交（会丢失最近一次提交的所有更改），慎用</td></tr> <tr><td>分支管理</td> <td><code>git branch</code></td> <td>列出本地所有分支</td></tr> <tr><td></td> <td><code>git branch &lt;branch-name&gt;</code></td> <td>创建新分支</td></tr> <tr><td></td> <td><code>git checkout &lt;branch-name&gt;</code></td> <td>切换到指定分支</td></tr> <tr><td></td> <td><code>git switch &lt;branch-name&gt;</code></td> <td>（Git 2.23+）切换分支（推荐替代 checkout）</td></tr> <tr><td></td> <td><code>git checkout -b &lt;branch-name&gt;</code></td> <td>创建并切换新分支</td></tr> <tr><td></td> <td><code>git branch -d &lt;branch-name&gt;</code></td> <td>删除已合并的分支</td></tr> <tr><td></td> <td><code>git branch -D &lt;branch-name&gt;</code></td> <td>强制删除分支（即使未合并）</td></tr> <tr><td></td> <td><code>git merge &lt;branch-name&gt;</code></td> <td>合并指定分支到当前分支</td></tr> <tr><td>远程操作</td> <td><code>git remote -v</code></td> <td>查看远程仓库地址</td></tr> <tr><td></td> <td><code>git remote add origin &lt;url&gt;</code></td> <td>添加远程仓库（通常命名为 origin）</td></tr> <tr><td></td> <td><code>git push -u origin &lt;branch&gt;</code></td> <td>首次推送本地分支到远程，并设置上游跟踪</td></tr> <tr><td></td> <td><code>git push</code></td> <td>推送当前分支到关联的远程分支</td></tr> <tr><td></td> <td><code>git pull</code></td> <td>拉取远程更新并合并（默认相当于 fetch + merge）</td></tr> <tr><td></td> <td><code>git fetch</code></td> <td>获取远程更新但不合并</td></tr> <tr><td>标签管理</td> <td><code>git tag</code></td> <td>列出所有标签</td></tr> <tr><td></td> <td><code>git tag &lt;tagname&gt;</code></td> <td>创建轻量标签</td></tr> <tr><td></td> <td><code>git tag -a &lt;tagname&gt; -m &quot;message&quot;</code></td> <td>创建带注释的标签</td></tr> <tr><td></td> <td><code>git push origin &lt;tagname&gt;</code></td> <td>推送指定标签到远程</td></tr> <tr><td></td> <td><code>git push origin --tags</code></td> <td>推送所有标签到远程</td></tr> <tr><td>其他实用命令</td> <td><code>git stash</code></td> <td>临时保存当前工作区和暂存区的修改</td></tr> <tr><td></td> <td><code>git stash pop</code></td> <td>恢复最近一次 stash 的内容</td></tr> <tr><td></td> <td><code>git reflog</code></td> <td>查看 HEAD 变更记录（可用于找回「丢失」的提交）</td></tr> <tr><td></td> <td><code>git show &lt;commit-id&gt;</code></td> <td>显示某次提交的详细信息</td></tr></tbody></table> <h2 id="修改已推送的-commit-信息" tabindex="-1">修改已推送的 commit 信息 <a class="header-anchor" href="#修改已推送的-commit-信息" aria-label="Permalink to &quot;修改已推送的 commit 信息&quot;">​</a></h2> <p>场景：最近一次 commit 已经推送到远端，发现提交信息写错了，想改过来。前提是本地处于该分支最新状态。</p> <ol><li><code>git commit --amend</code> 进入编辑器（默认 vim）：按 <code>i</code> 进入编辑模式修改提交信息，编辑完按 <code>Esc</code>，输入 <code>:wq</code> 保存退出</li> <li><code>git push -f</code> 强制推送，覆盖远端</li></ol> <p>编辑器不一定是 vim，能保存即可，例如 nano：<code>Ctrl+O</code> 保存，<code>Ctrl+X</code> 退出。</p> <p>force push 会改写远端历史：该 commit 已被他人拉取时，会给他们制造冲突，共享分支上慎用。更稳妥的写法是 <code>git push --force-with-lease</code>——远端在本地不知情时被更新过，推送会被拒绝，降低覆盖他人提交的风险。</p> <h2 id="要点" tabindex="-1">要点 <a class="header-anchor" href="#要点" aria-label="Permalink to &quot;要点&quot;">​</a></h2> <ul><li>查任意命令的权威说明用 <code>git help &lt;command&gt;</code></li> <li><code>--hard</code> 与 force push 都是破坏性操作，执行前确认自己清楚后果</li> <li>Git 2.23 起分支操作推荐用 <code>git switch</code>、撤销暂存推荐用 <code>git restore --staged</code>，职责比 <code>git checkout</code> 清晰</li></ul>',21)])])}const u=d(r,[["render",i]]);export{s as __pageData,u as default};
